package com.retailflow.pos.customer;
import com.retailflow.pos.sales.*;import jakarta.persistence.EntityNotFoundException;import java.util.*;import org.springframework.stereotype.Service;
@Service public class CustomerService{private final CustomerRepository r;private final InvoiceRepository invoices;public CustomerService(CustomerRepository r,InvoiceRepository invoices){this.r=r;this.invoices=invoices;}public List<Customer>list(){return r.findAll();}public Customer get(String id){return r.findById(id).orElseThrow(()->new EntityNotFoundException("Customer not found"));}public Customer save(Customer c){return r.save(c);}public void delete(String id){r.delete(get(id));}public List<Invoice>invoices(String id){get(id);return invoices.findByCustomerIdOrderByInvoiceDateDesc(id);}}
